fn solve(n: i8) -> i8 {
    // If n is odd, no rectangle possible
    if n % 2 != 0 {
        return 0;
    }

    // n is even, compute half-perimeter
    let half = n / 2;

    // Count unordered pairs (a, b) with a < b and a + b = half
    // The number of such pairs is floor((half - 1) / 2)
    let pairs = (half - 1) / 2;

    // Adjust for squares when n is divisible by 4
    if n % 4 == 0 {
        // When n divisible by 4, half is even, so a = b = half/2 is possible
        // We need to exclude that square case
        pairs - 1
    } else {
        pairs
    }
}